/* Collectible trigger: deletes itself once taken, else watches for its toucher. */
void block_cave_update(char *m) {
    int i;
    CaveLink *table_entry;
    float transposed_rotation_matrix[16];
    float relative_position[4];
    struct Moby *moby = (struct Moby *)m;
    unsigned short id = moby->save_id;
    if (orxon_collected_flags_base.collected[(short)id] != 0
        || (*(int *)(help_stats_base + 0xAB75 + (((short)id >> 5) * 4 + (g_current_level_index_r << 8))) >> (id & 0x1F)) & 1) {
        DeleteMoby(moby);
        return;
    }
    moby->draw_dist = 0x80;
    table_entry = (CaveLink *)orxon_moby_hits;
    for (i = 0; i < 0x40; i++, table_entry++) {
        if (table_entry->owner == moby) {
            if (table_entry->flags & 0x20000) {
                struct Moby *other_moby = table_entry->other;
                if (other_moby->oclass == 0xAC || other_moby->oclass == 0x99) {
                    FastVecSub(relative_position, &moby->pos, &other_moby->pos);
                    matrix_from_basis_rows(transposed_rotation_matrix, &moby->rot_row0);
                    transform_vector(relative_position, relative_position, transposed_rotation_matrix);
                    if (relative_position[0] > 0.25f) {
                        *(int *)(help_stats_base + 0xAB75 + (((short)moby->save_id >> 5) * 4 + (g_current_level_index_r << 8))) |= 1 << (moby->save_id & 0x1F);
                        orxon_moby_killed[(short)moby->save_id >> 5] |= 1 << (moby->save_id & 0x1F);
                        DeleteMoby(moby);
                        return;
                    }
                    table_entry->owner = 0;
                } else {
                    table_entry->owner = 0;
                }
            }
        }
    }
}
